{
  "name": "Keithley 195 数字万用表",
  "name_en": "Keithley 195 Digital Multimeter",
  "manufacturer": "Keithley",
  "description": "Keithley 195 是一台 5 位半自动量程数字万用表，用于实验室台式电学测量。基础型号可进行直流电压和电阻测量，配合相应选件还可支持交流电压、直流电流和交流电流测量，适合器件表征、通用电参数测试和精密读数采集。",
  "description_en": "The Keithley 195 is a 5.5-digit auto-ranging digital multimeter for bench-top electrical measurements in the lab. The base instrument measures DC voltage and resistance, and with suitable options it can also support AC voltage, DC current, and AC current measurements. It is suited for device characterization, general electrical testing, and precision readout tasks.",
  "tag_hints": [
    "digital multimeter",
    "5.5-digit measurement",
    "auto-ranging",
    "DC voltage measurement",
    "resistance measurement",
    "bench electrical testing"
  ],
  "actions": [
    {
      "action_name": "auto-auto_range",
      "description": "开启自动量程。",
      "description_en": "Enable auto range."
    },
    {
      "action_name": "auto-input_range",
      "description": "获取/设置输入量程。",
      "description_en": "Get/set the input range."
    },
    {
      "action_name": "auto-measure",
      "description": "执行一次测量。",
      "description_en": "Perform a one-time measurement."
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置测量模式。",
      "description_en": "Get/set the measurement mode."
    },
    {
      "action_name": "auto-relative",
      "description": "获取/设置相对测量（零点抑制）模式。",
      "description_en": "Get/set the relative measurement (zero suppression) mode."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发设备执行已接收的命令。",
      "description_en": "Trigger the instrument to execute received commands."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取/设置触发模式。",
      "description_en": "Get/set the trigger mode."
    },
    {
      "action_name": "auto-get_status_word",
      "description": "获取状态字。",
      "description_en": "Get the status word."
    },
    {
      "action_name": "auto-parse_status_word",
      "description": "解析状态字。",
      "description_en": "Parse the status word."
    }
  ]
}

